let potpalette = ["#c34c8a", "#88cfcb", "#2c898b", "#df9540", "#3d100d", "#e95b5a", "#f9c597", "#d6ccb7"];
let greens = ["#78c372", "#429269", "#266933", "#83b741", "#c1dc8f", "#17834e", "#199d5e", "#71d69d"];

let count = 5;
let lastcount = 5;
let trigger = true;
let lapse = 0; // mouse timer global to debounce

function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight)); // You are such a square......
	background(255);
}

function draw() {
	count = constrain(floor(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 10)), 1, 10); // map (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) to count

	if (!trigger && count == lastcount) { // no need to redraw
		return;
	}

	background(255);
	let cellsize = width / count;
	for (j = 0; j < count; j++) {
		for (i = 0; i < count; i++) {
			let x_pos = width * i / count + cellsize * 0.5;
			let y_pos = height * j / count + cellsize * 0.90;
			pottedplant(x_pos, y_pos, cellsize * 1, cellsize * 1);
		}
	}
	lastcount = count;
	trigger = false;
}

function mousePressed() {
	if (millis() - lapse < 400) {
		return (false);
	}
	lapse = millis();
	if (mouseButton === RIGHT) { // save image
		let datetime = nf([month(), day(), hour(), minute(), second()], 2);
		save("img_" + year() + datetime.join("") + ".jpg");
	} else if (mouseButton === CENTER) {
		// nothing here
	} else { // Left click
		trigger = true;     // trigger a redraw
	}
	return (false)
}

//
//  Draw a potted plant
//
function pottedplant(_x, _y, _w, _h) {  // bottom center of pot, total width and height of pot and plant
	let potheight = _h * random(0.2, 0.4);  // not too big, not too small
	let plantheight = _h - potheight;

	let potwidth = potheight * random(0.8, 2);
	let plantwidth = potwidth * random(0.4, 0.7);

	let levels = floor(random(2, 8));
	let leaves = floor(random(5, 10));

	plant(_x, _y - potheight, leaves, levels, plantwidth, plantheight, random(0.6,2));  // last value controls the overall shape
	pot(_x, _y - potheight, potwidth, potheight);
}

//
//  Draw a pot
//
function pot(_x, _y, _w, _h) {
	let rim = random(potpalette);
	let body = random(potpalette);
	while (body === rim) body = random(potpalette);

	push();
	noStroke();
	rectMode(CORNERS)
	fill(rim);
	translate(_x - _w / 2, _y + _h);
	rect(0, 0, _w, -_h, _w / 40)
	fill(body);
	rect(0, 0, _w, -_h * random(0.5, 0.9))
	fill(255);
	//cut sides
	let f = random(_w * 0.1, _w * 0.35);
	beginShape();
	vertex(0, -_h);
	bezierVertex(0, 0, f, 0, f, 0);
	bezierVertex(f, 0, 0, _h * 0.1, -_w * 0.1, _h * 0.1);
	endShape(CLOSE);
	push();
	translate(_w, 0);
	scale(-1, 1);
	beginShape();
	vertex(0, -_h);
	bezierVertex(0, 0, f, 0, f, 0);
	bezierVertex(f, 0, 0, _h * 0.1, -_w * 0.1, _h * 0.1);
	endShape(CLOSE);
	pop();
	pop();
	//gloss
	push();
	noStroke();
	fill(255, 255, 255, 64);
	translate(_x, _y + 0.02 * _h)
	beginShape();
	vertex(-_w * 0.45, 0);
	bezierVertex(f - _w * 0.65, _h, 0, _h, _w * 0.2, 0);
	endShape(CLOSE);

	pop();
}

//
//  Draw a plant
//
function plant(_x, _y, _xc, _yc, _w, _h, _factor) {

	push();
	drawingContext.shadowOffsetX = -2;
	drawingContext.shadowOffsetY = 0;
  drawingContext.shadowBlur= _w/20;
  drawingContext.shadowColor = 'rgba(0,0,0,0.44)';

	fill(random(greens));
	noStroke();
	translate(_x, _y);
	ellipse(0, 0, _w, _h / 2);
	let x_spacing = _w / _xc;
	for (let row = 0; row < _yc; row++) {
		let leafs = floor(_xc - _yc * pow(((_yc - row - 1) / _yc), _factor)); // power factor changes the "shape" of the plant
		for (let l = 0; l < leafs; l++) {
			let xpos = map(l, 0, leafs - 1, -x_spacing * leafs / 2, x_spacing * leafs / 2);
			let ypos = map(row, 0, _yc, _h / 2, 0);
			if (leafs == 1) {
				ypos -= 1 * _h / _yc;
			}
			let rot = map(xpos, -_w / 2, _w / 2, -0.4, 0.4);
			if (isNaN(rot)) {  //catch a bad map
				rot = 0;
			}
			leaf(xpos, 0, 2.2 * _w / _xc, _h / _yc, ypos, rot, rot); //x,y, width, height, y_position, rotate, leaf-twist
		}
	}
	pop();
}

//
//  Draw a leaf
//
function leaf(_x, _y, _w, _h, _p, _r, _t) {
	let random = min(_w, _h) / 4; // leaf shape distortion amount

	push();
	strokeCap(ROUND);
	strokeJoin(ROUND);
	translate(_x, _y + _h / 2);
	scale(1, -1);
	translate(0, _p);
	rotate(-_r);
	beginShape();
	vertex(-_w / 4, 0);
	r_bezierVertex(-_w / 2, _h / 4, -_w / 2, _h / 2, _t * _h, _h, random);
	r_bezierVertex(_w / 2, _h / 2, _w / 2, _h / 4, _w / 4, 0, random);
	bezierVertex(0, -_h / 4, 0, -_h / 4, -_w / 4, 0);
	endShape();

	// shade
	noStroke();
	fill(0, 0, 0, 20);
	beginShape();
	vertex(-_w / 4, 0);
	r_bezierVertex(-_w / 2, _h / 4, -_w / 2, _h / 2, _t * _h, _h, random);
	bezierVertex(_w / 2, _h / 2, 0, -_h / 4, -_w / 4, 0);
	endShape();

	// highlight
	noStroke();
	fill(255, 255, 255, 64);
	beginShape();
	vertex(_t * _h, _h);
	r_bezierVertex(_w / 2, _h / 2, _w / 2, _h / 4, _w / 4, 0, random);
	endShape(CLOSE);

	pop();
}

//
//  random version of vertex()
//
function r_vertex(x, y, j) {
	j = (j === undefined) ? 0.2 : j;
	vertex(x + random(-j / 2, j / 2), y + random(-j / 2, j / 2));
}

//
//  random version of bezierVertex()
//
function r_bezierVertex(x2, y2, x3, y3, x4, y4, j) {
	j = (j === undefined) ? 0.2 : j;
	bezierVertex(x2 + random(-j / 2, j / 2), y2 + random(-j / 2, j / 2), x3 + random(-j / 2, j / 2), y3 + random(-j / 2, j / 2), x4 + random(-j / 2, j / 2), y4 + random(-j / 2, j / 2));
}
